{
  "schemaVersion": "0.2",
  "slug": "workspace-split",
  "name": "WorkspaceSplit",
  "status": "experimental",
  "purpose": "Master–detail (optional tools) workspace that morphs single-column ↔ split via container queries.",
  "scenarios": [
    "Queue + editor workspace that stacks on phone and splits from tablet",
    "Queue + canvas + tools three-pane desktop layout without freezing CSS Grid"
  ],
  "props": {
    "master": {
      "type": "node",
      "required": true,
      "description": "Master / queue column."
    },
    "detail": {
      "type": "node",
      "required": true,
      "description": "Detail / canvas column."
    },
    "tools": {
      "type": "node",
      "required": false,
      "description": "Optional tools / inspector pane. Stacks on compact; under detail on tablet; third column at desktop."
    },
    "masterWidth": {
      "type": "string",
      "required": false,
      "default": "16rem",
      "description": "Preferred master column width from tablet up."
    },
    "toolsWidth": {
      "type": "string",
      "required": false,
      "default": "16rem",
      "description": "Preferred tools column width at desktop."
    },
    "collapseBelow": {
      "type": "string",
      "required": false,
      "default": "48rem",
      "description": "Documented threshold. Morph uses token breakpoints 48rem/80rem; custom lengths are not applied."
    },
    "scrollMode": {
      "type": "enum",
      "required": false,
      "values": [
        "shell",
        "panes",
        "none"
      ],
      "default": "shell",
      "description": "Unique scroll owner. shell (default): AppShell __main scrolls, panes do not. panes: fill host and pane overflow:auto. none: no default pane scroll."
    },
    "masterScroll": {
      "type": "boolean",
      "required": false,
      "default": null,
      "description": "Per-pane override. null/omitted follows scrollMode (true only for panes). Explicit true/false wins."
    },
    "detailScroll": {
      "type": "boolean",
      "required": false,
      "default": null,
      "description": "Per-pane override. null/omitted follows scrollMode (true only for panes). Explicit true/false wins."
    },
    "toolsScroll": {
      "type": "boolean",
      "required": false,
      "default": null,
      "description": "Per-pane override. null/omitted follows scrollMode (true only for panes). Explicit true/false wins."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Default."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "card",
      "stack"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not freeze a desktop CSS Grid or Stack direction=row for the same master/detail job — that fights Navigation morph and squeezes columns on compact.",
    "Do not nest a second AppShell Navigation inside a pane.",
    "Do not enable pane *Scroll (or scrollMode=panes) and also fight AppShell __main with a second overflow:auto — one scroll owner only.",
    "Do not nest a second WorkspaceSplit inside detail — nested splits always stack; use the outer tools slot."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Follows content.",
    "labeling": "As needed.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Named container workspace-split restyles the inner frame. Compact is one column; 48rem opens master|detail; 80rem opens tools as a third column when present.",
    "breakpoints": {
      "compact": "Single column: master, then detail, then tools.",
      "medium": "Master | detail; tools stacks under detail when present.",
      "large": "Master | detail | tools when tools is present; otherwise master | detail."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "workspace-split",
    "states": [
      "default"
    ],
    "intents": [
      "layout-split"
    ]
  }
}

/*
 * Master–detail (optional tools) workspace. The root is the query container;
 * only `.cu-workspace-split__frame` (a descendant) is restyled — never the
 * container itself (容器查询与三端规范 §2).
 *
 * Thresholds are on *this* container's inline size (often AppShell `__main`,
 * which is already narrower than the shell when Navigation is a side rail).
 *
 * Compact (<48rem): single column (master → detail → tools).
 * Tablet (48rem): master | detail; tools stacks under detail when present.
 * Wide (80rem): master | detail | tools when tools is present — matches
 * breakpoint.desktop. Nested math: 80rem shell − 16rem sidebar ≈ 64rem main,
 * so three-pane stays closed at 1280 CSS px; needs ~96rem shell (or a
 * standalone ≥80rem host) before tools sit beside detail.
 *
 * Nested `.cu-workspace-split` always stacks — outer owns the morph. Put tools
 * on the outer `#tools` / `tools` slot instead of nesting another split.
 *
 * Scroll (data-scroll-mode):
 * - shell (default): grow with content; AppShell `__main` is the scroll owner.
 * - panes: fill the host; panes use overflow:auto (dashboard).
 * - none: no default pane scroll; consumer owns overflow via ScrollPane / *Scroll.
 */
.cu-workspace-split {
  container-name: workspace-split;
  container-type: inline-size;
  inline-size: 100%;
  block-size: 100%;
  min-block-size: 0;
  min-inline-size: 0;
  overflow-x: clip;
}

.cu-workspace-split[data-scroll-mode='shell'],
.cu-workspace-split[data-scroll-mode='none'] {
  block-size: auto;
  min-block-size: 100%;
}

.cu-workspace-split[data-scroll-mode='panes'] {
  block-size: 100%;
  min-block-size: 0;
  overflow: hidden;
}

.cu-workspace-split__frame {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas:
    "master"
    "detail";
  gap: var(--cu-space-4, var(--cu-space-3));
  block-size: 100%;
  min-block-size: 0;
  min-inline-size: 0;
  align-items: stretch;
  overflow-x: clip;
}

.cu-workspace-split[data-scroll-mode='shell'] .cu-workspace-split__frame,
.cu-workspace-split[data-scroll-mode='none'] .cu-workspace-split__frame {
  block-size: auto;
  min-block-size: 100%;
}

.cu-workspace-split[data-scroll-mode='panes'] .cu-workspace-split__frame {
  block-size: 100%;
  min-block-size: 0;
  overflow: hidden;
}

.cu-workspace-split:has(.cu-workspace-split__tools) .cu-workspace-split__frame {
  grid-template-areas:
    "master"
    "detail"
    "tools";
}

.cu-workspace-split__master,
.cu-workspace-split__detail,
.cu-workspace-split__tools {
  display: flex;
  flex-direction: column;
  min-block-size: 0;
  min-inline-size: 0;
  max-inline-size: 100%;
}

.cu-workspace-split__master {
  grid-area: master;
}

.cu-workspace-split__detail {
  grid-area: detail;
}

.cu-workspace-split__tools {
  grid-area: tools;
}

.cu-workspace-split__pane--scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: auto;
}

/*
 * Nested split: always stack. Avoids queue|canvas|tools crush when a detail
 * pane hosts another WorkspaceSplit (common consumer mistake).
 */
.cu-workspace-split .cu-workspace-split .cu-workspace-split__frame {
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas:
    "master"
    "detail";
  grid-template-rows: none;
}

.cu-workspace-split .cu-workspace-split:has(.cu-workspace-split__tools) .cu-workspace-split__frame {
  grid-template-areas:
    "master"
    "detail"
    "tools";
}

@container workspace-split (min-width: 48rem) {
  .cu-workspace-split__frame {
    grid-template-columns: minmax(0, var(--cu-workspace-master-width, 16rem)) minmax(0, 1fr);
    grid-template-areas: "master detail";
    grid-template-rows: minmax(0, 1fr);
  }

  .cu-workspace-split:has(.cu-workspace-split__tools) .cu-workspace-split__frame {
    grid-template-columns: minmax(0, var(--cu-workspace-master-width, 16rem)) minmax(0, 1fr);
    grid-template-areas:
      "master detail"
      "master tools";
    grid-template-rows: minmax(0, 1fr) auto;
  }

  /* Shell/none: rows size to content so AppShell `__main` can scroll. */
  .cu-workspace-split[data-scroll-mode='shell'] .cu-workspace-split__frame,
  .cu-workspace-split[data-scroll-mode='none'] .cu-workspace-split__frame {
    grid-template-rows: auto;
  }

  .cu-workspace-split[data-scroll-mode='shell']:has(.cu-workspace-split__tools) .cu-workspace-split__frame,
  .cu-workspace-split[data-scroll-mode='none']:has(.cu-workspace-split__tools) .cu-workspace-split__frame {
    grid-template-rows: auto auto;
  }
}

@container workspace-split (min-width: 80rem) {
  .cu-workspace-split:has(.cu-workspace-split__tools) .cu-workspace-split__frame {
    grid-template-columns:
      minmax(0, var(--cu-workspace-master-width, 16rem))
      minmax(0, 1fr)
      minmax(0, var(--cu-workspace-tools-width, 16rem));
    grid-template-areas: "master detail tools";
    grid-template-rows: minmax(0, 1fr);
  }

  .cu-workspace-split[data-scroll-mode='shell']:has(.cu-workspace-split__tools) .cu-workspace-split__frame,
  .cu-workspace-split[data-scroll-mode='none']:has(.cu-workspace-split__tools) .cu-workspace-split__frame {
    grid-template-rows: auto;
  }
}

import type { CSSProperties, ReactNode } from 'react'
import './styles.css'

/**
 * Who owns overflow when WorkspaceSplit sits in AppShell `__main`.
 * - `shell` (default): panes do not scroll; `__main` grows/scrolls. Safe for
 *   short / EmptyState content — no nested scrollbars.
 * - `panes`: fill the main scrollport; each pane scrolls (dashboard / fixed
 *   viewport). AppShell `__main` stops scrolling when the split is a direct child.
 * - `none`: neither default pane scroll nor shell fill-for-panes; use
 *   `ScrollPane` / per-pane `*Scroll` for any overflow.
 */
export type WorkspaceSplitScrollMode = 'shell' | 'panes' | 'none'

export interface WorkspaceSplitProps {
  master: ReactNode
  detail: ReactNode
  /** Optional third pane (tools / inspector). Stacks on compact; side column at desktop. */
  tools?: ReactNode
  masterWidth?: string
  toolsWidth?: string
  /**
   * Documented collapse threshold. Morph uses token-aligned breakpoints
   * (48rem master|detail, 80rem three-pane) via `@container` — custom lengths
   * are not applied (container queries cannot safely consume arbitrary CSS
   * variables as query bounds across browsers).
   */
  collapseBelow?: string
  /**
   * Scroll owner strategy. Default `shell` — do not nest pane `overflow: auto`
   * under AppShell `__main`. Use `panes` for fixed-viewport dashboards.
   */
  scrollMode?: WorkspaceSplitScrollMode
  /** Per-pane override. When omitted/null, follows `scrollMode` (`panes` → true). */
  masterScroll?: boolean | null
  detailScroll?: boolean | null
  toolsScroll?: boolean | null
  className?: string
}

function resolvePaneScroll(
  mode: WorkspaceSplitScrollMode,
  override?: boolean | null,
): boolean {
  // null/undefined = follow scrollMode. Explicit true/false wins.
  // (Vue Boolean props coerce absent → false unless defaulted to null.)
  if (override === true) return true
  if (override === false) return false
  return mode === 'panes'
}

export function WorkspaceSplit({
  master,
  detail,
  tools,
  masterWidth = '16rem',
  toolsWidth = '16rem',
  collapseBelow = '48rem',
  scrollMode = 'shell',
  masterScroll,
  detailScroll,
  toolsScroll,
  className,
}: WorkspaceSplitProps) {
  const classes = ['cu-workspace-split', className].filter(Boolean).join(' ')
  const style = {
    ['--cu-workspace-master-width' as string]: masterWidth,
    ['--cu-workspace-tools-width' as string]: toolsWidth,
    ['--cu-workspace-collapse-below' as string]: collapseBelow,
  } satisfies CSSProperties
  const masterScrollOn = resolvePaneScroll(scrollMode, masterScroll)
  const detailScrollOn = resolvePaneScroll(scrollMode, detailScroll)
  const toolsScrollOn = resolvePaneScroll(scrollMode, toolsScroll)

  return (
    <div
      className={classes}
      data-ai-role="workspace-split"
      data-ai-intent="layout-split"
      data-ai-state="default"
      data-scroll-mode={scrollMode}
      style={style}
    >
      <div className="cu-workspace-split__frame">
        <div
          className={[
            'cu-workspace-split__master',
            masterScrollOn ? 'cu-workspace-split__pane--scroll' : '',
          ]
            .filter(Boolean)
            .join(' ')}
        >
          {master}
        </div>
        <div
          className={[
            'cu-workspace-split__detail',
            detailScrollOn ? 'cu-workspace-split__pane--scroll' : '',
          ]
            .filter(Boolean)
            .join(' ')}
        >
          {detail}
        </div>
        {tools != null ? (
          <div
            className={[
              'cu-workspace-split__tools',
              toolsScrollOn ? 'cu-workspace-split__pane--scroll' : '',
            ]
              .filter(Boolean)
              .join(' ')}
          >
            {tools}
          </div>
        ) : null}
      </div>
    </div>
  )
}
